import{z as l,x as d,o as E,c as m,q as A,j as n,D as r,d as s,s as i,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"SRAM 与 DRAM 阵列","description":"","frontmatter":{"title":"SRAM 与 DRAM 阵列","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/memory-array-sram-dram.md","filePath":"cs/memory-array-sram-dram.md","lastUpdated":1791413859000}'),B={name:"cs/memory-array-sram-dram.md"};function p(D,a,R,M,c,C){const t=d("Mermaid");return E(),m("div",null,[a[2]||(a[2]=A('<h1 id="sram-与-dram-阵列" tabindex="-1">SRAM 与 DRAM 阵列 <a class="header-anchor" href="#sram-与-dram-阵列" aria-label="Permalink to &quot;SRAM 与 DRAM 阵列&quot;">​</a></h1><div class="epigraph"><p>寄存器存几十个字已经够贵；大批量比特改用阵列：静态交叉耦合一对，动态靠电容再定期刷新。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture；Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p>上一课<a href="/cs/counter-circuit">计数器</a>可以扫描地址。本课不重讲模 \\(M\\)，也不从文件系统另起。缺口是：寄存器堆和 FF 按比特复制，存 KiB 以上不划算。需要<strong>存储器阵列</strong>：译码、字线、位线，以及 SRAM 与 DRAM 两种单元。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n\\) 位地址应选出 \\(2^n\\) 行之一，读出字。缺口是组织：行译码器点亮字线，单元把数据放到位线，灵敏放大器判决——第一课的判决在这里再次出现。SRAM 六管（或类似）交叉耦合，静态保持，与锁存同族、更密。DRAM 一管一容，密度高，读破坏性，必须刷新：计数器课的定时在此落地。</p><p><span class="marginnote">直觉类比：DRAM 单元是只漏水的小水桶——读一次就得把水倒回去（读是破坏性的），平时还要按周期逐行补水（刷新）；SRAM 像两个互相钳制的开关，通电就一直稳住，代价是六个管子的面积。</span></p><p>本课钉阵列与两种单元。Cache、虚拟内存是体系结构课，不在本课。</p><h3 id="dram-不是「更慢的-sram」" tabindex="-1">DRAM 不是「更慢的 SRAM」 <a class="header-anchor" href="#dram-不是「更慢的-sram」" aria-label="Permalink to &quot;DRAM 不是「更慢的 SRAM」&quot;">​</a></h3><p>接口有行选、列选、预充电、刷新命令，延迟不是单周期 \\(t_{pd}\\) 能概括。把主存当组合 ROM 画进单周期图，是教学抽象（Patterson 的组合数据存储器），实现上是 DRAM 控制器跨多拍——<a href="/cs/multicycle-microcode">多周期</a>会碰到。SRAM 用作片上寄存器堆、Cache 体，延迟更接近若干门。</p><p><span class="marginnote">Harris 画 6T SRAM 与 1T1C DRAM。Patterson/Hennessy 把存储器延迟放进 CPU 性能。纠错码可加在阵列外，几何已在 ECC 课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>地址拆行、列。读：字线开，位线差分放大。写：驱动位线再开字线。DRAM 刷新：周期内遍历行。端口：单口、双口 SRAM 改变线数与译码。</p><p><span class="marginnote">数字实例：10 位地址若单级译码，要在一排里点亮 \\(2^{10}=1024\\) 根字线之一；拆成 5 位行、5 位列，只需两个「32 选 1」小译码器，引线从上千根降到约 64 根——阵列做得大，靠的就是把译码摊成两级。</span></p>',13)),(E(),n(o,null,{default:r(()=>[i(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADDR%5B%22%E5%9C%B0%E5%9D%80%22%5D%20--%3E%20DEC%5B%22%E8%A1%8C%2F%E5%88%97%E8%AF%91%E7%A0%81%22%5D%0A%20%20DEC%20--%3E%20CELL%5B%22SRAM%20%E6%88%96%20DRAM%20%E5%8D%95%E5%85%83%22%5D%0A%20%20CELL%20--%3E%20BL%5B%22%E4%BD%8D%E7%BA%BF%E5%88%A4%E5%86%B3%22%5D%0A%20%20BL%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%97%B6%E9%92%9F%E5%9F%9F%E4%B8%8E%E7%A8%8B%E5%BA%8F%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"指令与数据在后课存储程序里都放阵列上。单周期教材常把指令存储器当 ROM/SRAM 组合读。写使能必须相对时钟满足建立保持：存储器端口也是时序元件。DRAM 刷新与 CPU 访存争用，由控制器仲裁，本课只承认冲突存在。",-1)),a[5]||(a[5]=e("p",null,"两种单元用不同的物理手段存同一个比特，各自的代价决定了它们的位置：",-1)),(E(),n(o,null,{default:r(()=>[i(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20LR%0A%20%20BIT%5B%22%E5%AD%98%201%20%E4%B8%AA%E6%AF%94%E7%89%B9%22%5D%20--%3E%20SR%5B%22SRAM%EF%BC%9A6%20%E7%AE%A1%E4%BA%A4%E5%8F%89%E8%80%A6%E5%90%88%22%5D%0A%20%20BIT%20--%3E%20DR%5B%22DRAM%EF%BC%9A1%20%E7%AE%A1%201%20%E7%94%B5%E5%AE%B9%22%5D%0A%20%20SR%20--%3E%20KEEP%5B%22%E9%80%9A%E7%94%B5%E5%8D%B3%E4%BF%9D%E6%8C%81%EF%BC%8C%E6%97%A0%E9%9C%80%E5%88%B7%E6%96%B0%22%5D%0A%20%20KEEP%20--%3E%20ONCHIP%5B%22%E7%89%87%E4%B8%8A%20Cache%20%E4%B8%8E%E5%AF%84%E5%AD%98%E5%99%A8%E5%A0%86%22%5D%0A%20%20DR%20--%3E%20LEAK%5B%22%E7%94%B5%E5%AE%B9%E6%BC%8F%E7%94%B5%EF%BC%8C%E9%A1%BB%E5%91%A8%E6%9C%9F%E5%88%B7%E6%96%B0%22%5D%0A%20%20LEAK%20--%3E%20MAIN%5B%22%E5%A4%A7%E5%AE%B9%E9%87%8F%E4%B8%BB%E5%AD%98%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=A('<p><span class="marginnote">常见误区：初学者容易以为 DRAM 慢在电容充放电。真正的延迟大头是多拍协议——行选、列选、预充电——加上控制器要在刷新与 CPU 访存之间排队仲裁；这也是教材把主存画成单周期读时必须声明「教学抽象」的原因。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲闪存浮栅、磁盘磁层。不把 NUMA、一致性协议提前。电容怎样在硅上做出来，不是本课的电路问题。</p><p>后课默认：大批量存储是阵列；片上多用 SRAM，主存是 DRAM 加控制器。读出是判决后的比特串。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>阵列 = 译码 + 单元 + 位线判决。</li><li>SRAM 静态保持；DRAM 电容须刷新、接口多拍。</li><li>寄存器堆是小而多口的 SRAM 特例，下一课之后才接到 ISA。</li><li>出处：Harris and Harris；Patterson and Hennessy, COD (RISC-V)。</li></ul>',6))])}const u=l(B,[["render",p]]);export{S as __pageData,u as default};
